package com.pipican.ore;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.pipican.effect.ClassEffect;
import java.util.List;

/**
 * A gear set's bonuses, loaded from {@code data/<namespace>/pipican/gear_set/<set>.json}: class effects that every
 * player gets, usually inside {@code pipican:conditional}s - "wearing all four pieces" ({@code pipican:wearing}) or
 * "holding one of the set's weapons" ({@code pipican:holding}). Generated by {@code tools/ore_builder/gear.py}.
 *
 * <pre>{@code { "effects": [ { "type": "pipican:conditional", "when": { "type": "pipican:wearing",
 *     "items": "#pipican:sets/crimtane/armor", "min": 4 }, "effects": [ ... ] } ] } }</pre>
 */
public record GearSet(List<ClassEffect> effects) {

    // Lazy: class effects may refer to registries loaded alongside this one.
    public static final Codec<GearSet> CODEC = RecordCodecBuilder.create(i -> i.group(
            Codec.lazyInitialized(() -> ClassEffect.CODEC).listOf().optionalFieldOf("effects", List.of()).forGetter(GearSet::effects)
    ).apply(i, GearSet::new));
}
